def is_valid_brackets(s):
    # Map opening brackets to their corresponding closing brackets
    pairs = {
        '(': ')',
        '[': ']',
        '{': '}'
    }

    # Stack to keep track of expected closing brackets
    stack = []

    for char in s:
        if char in pairs:
            # It's an opening bracket; push the expected closing bracket onto the stack
            stack.append(pairs[char])
        elif char in pairs.values():
            # It's a closing bracket; check if it matches the top of the stack
            if not stack:
                return False
            if stack[-1] == char:
                stack.pop()
            else:
                return False
        else:
            # Input contains non-bracket characters, which violates the problem constraint
            return False

    # If the stack is empty, all brackets were properly matched
    return len(stack) == 0
